import http from 'k6/http';
import { sleep } from 'k6';

export let options = {
  stages: [
    { duration: '2m', target: 5000 },
    { duration: '4m', target: 15000 },
    { duration: '4m', target: 15000 }
  ],
  thresholds: { 'http_req_duration': ['p(95)<120'] }
